import { Injectable } from "@nestjs/common";
import type { RecordedDto } from "#/modules/community/schema/dto/recorded.dto.ts";
import type { ViewInputDto } from "#/modules/community/schema/dto/view-input.dto.ts";
import { RecordViewUseCase } from "#/modules/community/features/counting/use-cases/record-view.repository.ts";

/**
 * The Counting contract the controller calls, then its implementation: each method
 * delegates to the use case for that operation. Regenerated by Dryv; the use cases hold the logic.
 */
export abstract class CommunityCountingService {
  abstract recordView(input: { body: ViewInputDto }): Promise<RecordedDto>;
}

@Injectable()
export class CommunityCountingServiceImpl extends CommunityCountingService {
  constructor(private readonly recordViewUseCase: RecordViewUseCase) {
    super();
  }

  recordView(input: { body: ViewInputDto }): Promise<RecordedDto> {
    return this.recordViewUseCase.execute(input);
  }
}
